-- Removes everything empty-store.sql created (and anything a test added to those stores).
delete from public.transaction_items where store_id in ('5c000000-0000-4000-8000-000000000001', '5d000000-0000-4000-8000-000000000001');
delete from public.transactions where store_id in ('5c000000-0000-4000-8000-000000000001', '5d000000-0000-4000-8000-000000000001');
delete from public.products where store_id in ('5c000000-0000-4000-8000-000000000001', '5d000000-0000-4000-8000-000000000001');
delete from public.categories where store_id in ('5c000000-0000-4000-8000-000000000001', '5d000000-0000-4000-8000-000000000001');
delete from public.profiles where store_id in ('5c000000-0000-4000-8000-000000000001', '5d000000-0000-4000-8000-000000000001');
delete from public.stores where id in ('5c000000-0000-4000-8000-000000000001', '5d000000-0000-4000-8000-000000000001');
delete from auth.identities where user_id in ('c1000000-0000-4000-8000-000000000001', 'c2000000-0000-4000-8000-000000000001', 'd1000000-0000-4000-8000-000000000001');
delete from auth.users where id in ('c1000000-0000-4000-8000-000000000001', 'c2000000-0000-4000-8000-000000000001', 'd1000000-0000-4000-8000-000000000001');
